begin;

alter table public.player_cards
  add column if not exists country_code text,
  add column if not exists first_name text,
  add column if not exists last_name text,
  add column if not exists name_on_shirt text,
  add column if not exists dob text,
  add column if not exists club text,
  add column if not exists height_cm integer,
  add column if not exists caps integer,
  add column if not exists goals integer,
  add column if not exists roster_source text default 'current_pool',
  add column if not exists roster_version text default 'pre_2026_world_cup_final_squad',
  add column if not exists card_art_url text,
  add column if not exists card_thumb_url text,
  add column if not exists price integer default 5000,
  add column if not exists star_level integer default 1;

-- Stage the full FIFA official squad before touching legacy cards.
create temporary table fifa_squad_import (
  team text,
  player_name text,
  player_name_en text,
  country_code text,
  position text,
  shirt_number integer,
  first_name text,
  last_name text,
  name_on_shirt text,
  dob text,
  club text,
  height_cm integer,
  caps integer,
  goals integer,
  rarity text,
  price integer,
  star_level integer,
  card_art_url text,
  card_thumb_url text,
  roster_source text,
  roster_version text
) on commit drop;

insert into fifa_squad_import (
  team,
  player_name,
  player_name_en,
  country_code,
  position,
  shirt_number,
  first_name,
  last_name,
  name_on_shirt,
  dob,
  club,
  height_cm,
  caps,
  goals,
  rarity,
  price,
  star_level,
  card_art_url,
  card_thumb_url,
  roster_source,
  roster_version
)
